import re
import pandas as pd
from datetime import date


def _is_null(v):
    if v is None:
        return True
    try:
        if isinstance(v, float) and pd.isna(v):
            return True
    except Exception:
        pass
    try:
        if pd.isna(v):
            return True
    except Exception:
        pass
    return False


def _trim(s):
    # Trim only leading/trailing space characters (' ')
    if _is_null(s):
        return None
    s = str(s)
    return s.strip(' ')


_NUM_RE = re.compile(r'^[+-]?\d+(\.\d{1,2})?$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')


def _parse_number(txt):
    if txt is None:
        return None
    if not _NUM_RE.match(txt):
        return None
    try:
        return float(txt)
    except Exception:
        return None


def _parse_date(txt):
    if txt is None:
        return None
    if not _DATE_RE.match(txt):
        return None
    y, m, d = txt.split('-')
    try:
        y_i, m_i, d_i = int(y), int(m), int(d)
        return date(y_i, m_i, d_i)
    except Exception:
        return None


def run(inputs: dict) -> dict:
    df = inputs['raw_payments'].copy()

    # Ensure deterministic order by row_num
    df = df.sort_values('row_num', kind='mergesort').reset_index(drop=True)

    valid_rows = []
    reject_rows = []

    # Intermediate storage for rows that pass R1-R5
    passed_candidates = []  # list of dicts with row_num, payment_id_trimmed, account_id, amount, currency, pay_date

    for _, row in df.iterrows():
        row_num = row['row_num']
        payment_id_raw = row['payment_id']
        account_id = row['account_id']
        amount_txt_raw = row['amount_txt']
        currency_raw = row['currency']
        pay_date_txt_raw = row['pay_date_txt']

        # R1 MISSING_ID
        pid_trimmed = _trim(payment_id_raw)
        if pid_trimmed is None or pid_trimmed == '':
            reject_rows.append({'row_num': row_num, 'reject_reason': 'MISSING_ID'})
            continue

        # R2 BAD_AMOUNT
        amount_txt_trimmed = _trim(amount_txt_raw)
        parsed_amount = _parse_number(amount_txt_trimmed) if amount_txt_trimmed is not None else None
        if amount_txt_trimmed is None or parsed_amount is None:
            reject_rows.append({'row_num': row_num, 'reject_reason': 'BAD_AMOUNT'})
            continue

        # R3 NON_POSITIVE
        if parsed_amount <= 0:
            reject_rows.append({'row_num': row_num, 'reject_reason': 'NON_POSITIVE'})
            continue

        # R4 BAD_CURRENCY
        currency_trimmed = _trim(currency_raw)
        if currency_trimmed is None:
            reject_rows.append({'row_num': row_num, 'reject_reason': 'BAD_CURRENCY'})
            continue
        currency_upper = currency_trimmed.upper()
        if currency_upper not in ('USD', 'EUR', 'GBP'):
            reject_rows.append({'row_num': row_num, 'reject_reason': 'BAD_CURRENCY'})
            continue

        # R5 BAD_DATE
        date_txt_trimmed = _trim(pay_date_txt_raw)
        parsed_date = _parse_date(date_txt_trimmed) if date_txt_trimmed is not None else None
        if date_txt_trimmed is None or parsed_date is None:
            reject_rows.append({'row_num': row_num, 'reject_reason': 'BAD_DATE'})
            continue

        # Passed R1-R5; candidate for duplicate check
        passed_candidates.append({
            'row_num': row_num,
            'payment_id': pid_trimmed,
            'account_id': account_id,
            'amount': parsed_amount,
            'currency': currency_upper,
            'pay_date': parsed_date,
        })

    # R6 DUPLICATE: group by trimmed payment_id, keep lowest row_num
    if passed_candidates:
        cand_df = pd.DataFrame(passed_candidates)
        min_row_per_id = cand_df.groupby('payment_id')['row_num'].transform('min')
        is_valid = cand_df['row_num'] == min_row_per_id

        for idx, keep in zip(cand_df.index, is_valid):
            rec = cand_df.loc[idx]
            if keep:
                valid_rows.append({
                    'payment_id': rec['payment_id'],
                    'account_id': rec['account_id'],
                    'amount': rec['amount'],
                    'currency': rec['currency'],
                    'pay_date': rec['pay_date'],
                })
            else:
                reject_rows.append({'row_num': rec['row_num'], 'reject_reason': 'DUPLICATE'})

    valid_payments = pd.DataFrame(valid_rows, columns=['payment_id', 'account_id', 'amount', 'currency', 'pay_date'])
    payment_rejects = pd.DataFrame(reject_rows, columns=['row_num', 'reject_reason'])

    # Sort rejects by row_num for determinism (not strictly required but stable)
    if not payment_rejects.empty:
        payment_rejects = payment_rejects.sort_values('row_num', kind='mergesort').reset_index(drop=True)

    return {
        'valid_payments': valid_payments,
        'payment_rejects': payment_rejects,
    }
